from collections import deque,Counter

def comps(a, coords, pred):
    seen=set(); out=[]
    for r,c in coords:
        if (r,c) in seen or not pred(a[r][c]): continue
        q=[(r,c)]; seen.add((r,c)); cells=[]
        while q:
            x,y=q.pop(); cells.append((x,y))
            for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                if (nx,ny) in seen or nx<0 or nx>=len(a) or ny<0 or ny>=len(a[0]): continue
                if pred(a[nx][ny]): seen.add((nx,ny));q.append((nx,ny))
        out.append(cells)
    return out
